  str_mail_vote_title_92 = "Agradecimiento de Tina",
  str_mail_vote_title_93 = "Agradecimiento de Leyn",
  str_mail_vote_title_94 = "Agradecimiento de Matthieu",
  str_mail_vote_title_95 = "Agradecimiento de Anatoli",
  str_mail_vote_title_96 = "Agradecimiento de Yingel",
  str_mail_vote_title_97 = "Agradecimiento de Xuan Ji",
  str_mail_vote_title_98 = "Agradecimiento de Chen'ni",
  str_mail_vote_title_99 = "Agradecimiento de Luo Song",
  str_mail_vote_title_100 = "Apreciación de Rachel",
  str_mail_vote_title_101 = "Agradecimiento de Zeta",
  str_mail_vote_title_102 = "Aprecio de Batia",
  str_mail_vote_detail_1 = "Nunca esperé tal apoyo sólido de nadie... Gracias, Navegador. Yo también estaré a tu lado en retribución.",
  str_mail_vote_detail_2 = "¡Vaya, Navegador, te esforzaste al máximo solo para que tenga un bonito atuendo para usar? Oh, estoy tan conmovida, ¡te lanzaré unas Conchas de Agua Bendita ahora mismo!",
  str_mail_vote_detail_3 = "¿Cuál es el punto de un traje nuevo...? Pero si es de ti, lo espero con ansias... Solo quiero decir... gracias.",
  str_mail_vote_detail_4 = "Vaya, ¿todo ese esfuerzo por mi nuevo atuendo? ¡No deberías haberlo hecho! Que May la brisa de la tarde lleve mi gratitud hacia ti.",
  str_mail_vote_detail_5 = "Cuando crecía, nunca tuve ropa propia aparte de una variedad de uniformes. Gracias por hacerme pensar en este tema, Navegador.",
  str_mail_vote_detail_6 = "Gracias por tu persistencia, Navegador. Me has hecho darme cuenta de que tal vez sea hora de mejorar mi forma de vestir. Lo veo como una especie de disciplina y trabajaré para mantenerla.",
  str_mail_vote_detail_7 = "Es un honor para mí, como noble, obtener su reconocimiento y apoyo. Admito que no estoy familiarizado con la última moda. ¿Estaría bien escuchar sus pensamientos en algún momento?",
  str_mail_vote_detail_8 = "Gracias por tu confianza y apoyo. ¿Votaste por Carleen? Ella ha estado trabajando duro y espero que puedas cuidar de ella.",
  str_mail_vote_detail_9 = "Oh, el gran Navegante ♪ Parece que nos tienes mucho cariño ♪ Pero aún así ♪ No evita que tu línea de cabello retroceda ♪",
  str_mail_vote_detail_10 = "Gracias, Navegante, pero ¿cómo supiste que no tengo dinero para ropa? Permíteme invitarte a una ronda de café la próxima vez, si no te importa...",
  str_mail_vote_detail_11 = "Bueno, has estado ayudándome incondicionalmente todo este tiempo, así que no tengo idea de cómo puedo recompensarte... Lo sé, tocaré una melodía específicamente para ti cuando no haya nadie alrededor. ¿Está bien eso?",
  str_mail_vote_detail_12 = "Je, interesante. Para mí, siempre puedo usar otro conjunto de ropa bonita. Gracias. Oh, también te conseguiré algo moderno a cambio cuando tenga la oportunidad.",
  str_mail_vote_detail_13 = "Pude sentir la confianza de ti cuando votaste por mí. ¿Fue por afecto, valiente viajero?",
  str_mail_vote_detail_14 = "Sí, el apoyo oportuno es equivalente a golpear en el momento exacto, lo que requiere una mente de precisa habilidad que tú, Navegante, posees. Gracias, lo apreciaré mucho.",
  str_mail_vote_detail_15 = "Pfft, esto es incómodo. Deja de dar vueltas y dime lo que quieres de mí... Vaya, qué sorpresa tan agradable.",
  str_mail_vote_detail_16 = "Estás esforzándote mucho para hacerme feliz, ¿verdad? Entonces, ¿qué tipo de conjunto quieres que use?",
  str_mail_vote_detail_17 = "¿Quieres que aproveche la oportunidad? Lo aprecio, chico. Después de ganar, ¿qué tal si celebramos con un par de copas?",
  str_mail_vote_detail_18 = "Me acostumbré a esconderme en las sombras hace mucho tiempo, pero aún así pasaré tiempo con ustedes jóvenes de vez en cuando. Simplemente no esperaba tanto apoyo de tu parte. Está bien, te daré una ventaja de tres movimientos en nuestra próxima partida de ajedrez!",
  str_mail_vote_detail_19 = "No puedo comprender tu alegría y anticipación, pero gracias de todos modos. Para corresponder, ¿te gustaría tomar una siesta en el cofre de madera negra?",
  str_mail_vote_detail_20 = "Vaya, ¿es realmente para mí? Aunque estoy maldito, a veces tengo suerte, como recibir tu apoyo inquebrantable, Navegante. Por favor, permíteme pensar en cómo agradecerte...",
  str_mail_vote_detail_21 = "De todos modos, lo tomaré. Pero, ¿no es un desperdicio de dinero darme un nuevo atuendo? Modifícalo para que se ajuste a Robyn si gano, Boatscrapper.",
  str_mail_vote_detail_22 = "No tienes que gastar recursos en mí, Navegante. Gastos como mantener el Colossus y alojar a los invitados cuestan mucho dinero. Sin embargo, el pensamiento me hace feliz y me siento bendecido!",
  str_mail_vote_detail_23 = "¡Gracias por esto! Un atuendo resistente y ajustado que facilita el entrenamiento es justo lo que un guerrero necesita. Hablando de eso, ¿cuándo vas a entrenar conmigo por una vez?",
  str_mail_vote_detail_24 = "¡Ajá, realmente eres mi mejor amigo! Cualquier vestuario de disfraces siempre está a una \"última pieza\" de ser perfecto. ¡Estamos totalmente en sintonía! ¡Muchas gracias!",
  str_mail_vote_detail_25 = "No pensé que te importara tanto por mí. ¿Qué tal esto? Puedes tomar prestado cualquier atuendo nuevo que tenga, pero a cambio tienes que ser mi sujeto de prueba. Eso es justo, ¿verdad?",
  str_mail_vote_detail_26 = "Soy afortunado de ser amado por ti. La vida es corta, pero no es un desperdicio si uno se detiene a oler las rosas.",
  str_mail_vote_detail_27 = "La excelente \"skin\" definitivamente mejorará mi rendimiento en los juegos. ¡Supongo que finalmente lo entendiste, Navegador! ¡Lo aprecio mucho!",
  str_mail_vote_detail_28 = "Gracias por señalarme una nueva dirección. No puedo perder ante Reinhardt, al menos en cuanto a la ropa que tengo!",
  str_mail_vote_detail_29 = "¿Nuevo uniforme? ¿Esto significa una nueva arena? ¡Claro, sigue votando por mí! ¡Saldrás como un bandido cuando termine!",
  str_mail_vote_detail_30 = "De hecho, he recolectado muchos atuendos maravillosos durante mis aventuras contigo, Navegante, ¿y aún así guardarías esa preciada oportunidad para mí? Bueno, ¡me esforzaré por guardar el libro para ti!",
  str_mail_vote_detail_31 = "¡Solo te diré esto, miau! Siento tu amor por mí y eso me hace muy feliz, ¡miau! Después de probar esto, vamos a echar una siesta bajo el sol, ¡miau!",
  str_mail_vote_detail_32 = "¡Guau! ¡Lo entiendes! Algo para usar que es perfecto para luchar. —Benny\n¿Yo también consigo uno? Una decisión sabia que merece mi aprecio. —Curo",
  str_mail_vote_detail_33 = "Tu apoyo me ha dado mucha fuerza, ¡y eso te convierte en un digno amigo de la justicia! Si no te importa, ¡permíteme coser \"Justicia\" en tu ropa!",
  str_mail_vote_detail_34 = "¿Qué? Esto definitivamente no está en el plan, aunque no lo odio en absoluto. Hagamos que el atuendo personalizado sea parte del plan entonces. ¡Trabajaré duro en ello!",
  str_mail_vote_detail_35 = "Bueno, no es que me falten atuendos aquí, pero ya que votaste por mí, lo menos que puedo hacer es probármelo... No, no me malinterpretes, ¡no estoy esperando esto en absoluto!",
  str_mail_vote_detail_36 = "Sé lo que elegiste, así que permíteme agradecerte. Sin embargo, aunque un diamante es hermoso, lo que realmente cautiva es su significado, ¿estoy en lo correcto?",
  str_mail_vote_detail_37 = "No pensé que votarías por mí, Navegante. ¿Nuevo traje, eh? La idea me emociona. Probablemente pueda usarlo para mi próximo viaje de estudio.",
  str_mail_vote_detail_38 = "¡Wow, me encantan eventos como este! ¡Hace mucho tiempo que no compro un atuendo nuevo! Si gano un disfraz nuevo, tengo que mostrárselo a Louise y a Su Majestad de inmediato.",
  str_mail_vote_detail_39 = "¡Es increíble recibir tantos votos de ti! Permíteme realizar un truco de magia en agradecimiento. ¡Elfos, por favor preparen las cajas de dulces!",
  str_mail_vote_detail_40 = "¿Nuevo disfraz? ¡Creo que lo entiendo! Es como darle a mis herramientas y mechas una nueva capa de pintura de vez en cuando. Je, estoy ansioso por ver qué \"capa de pintura\" tienes para mí, Navegante.",
  str_mail_vote_detail_41 = "Bueno, no puedo decir que estaba interesado en esto, pero las balas, los cargadores y los casquillos están clamando por una nueva apariencia, así que déjame agradecerte en su nombre.",
  str_mail_vote_detail_42 = "¡Qué sorpresa! Sabes, podrías haber simplemente unido a Rediesel Wrench si me gustabas tanto. ¡Entonces no tendrías que votar y te daré los pantalones de mis piernas!",
  str_mail_vote_detail_43 = "¿Votaste por mí? ¡Estoy tan feliz! Me encantaría mostrar cualquier nuevo disfraz que obtenga a mi hermano y a ti, Navegante.",
  str_mail_vote_detail_44 = "¿Qué, tantos votos? ¿Cómo debería agradecerte? Nuevo disfraz... Estaré extasiado si es Coolster con guantes.",
  str_mail_vote_detail_45 = "El nuevo atuendo debe ser un disfraz hermoso diseñado especialmente para una estrella principal... ¡Ya no puedo esperar para subir al escenario! Al ver cuántas veces votaste por mí, ¡aquí tienes una entrada VIP para el concierto!",
  str_mail_vote_detail_46 = "Mucho amor de Rediesel y la novia ardiente! Tu ídolo Barbara también ha entrado en la competencia! ¡Tengo tu entusiasmo y apoyo! ¡Recibirás una foto firmada más tarde!",
  str_mail_vote_detail_47 = "Gracias por quererme. Si es posible, me gustaría que Eve también reciba un nuevo disfraz. ¿Votarás por ella también?",
  str_mail_vote_detail_48 = "No importa lo que usen los técnicos, pero aún así te agradeceré de antemano. Hombre, ¿otra fuga...? Permíteme ponerme al día contigo después de arreglarlo.",
  str_mail_vote_detail_49 = "He querido un nuevo atuendo durante mucho tiempo, pero ¿cómo lo descubriste? Estás esperando que te interrogue con él puesto, ¿verdad, Navegante?",
  str_mail_vote_detail_50 = "Sí, sí, todo va según lo esperado, pero aún así, se agradece su apoyo. Todo parte del plan de The Knowledge, estoy seguro.",
  str_mail_vote_detail_51 = "Oh, estás votando por mí. Está bien, esperaré el resultado. Pero si noto que hay manipulación, tendrán que enfrentarse a mis espinas.",
  str_mail_vote_detail_52 = "Navegante, incluso cuando votas por mí, todavía... No, pensándolo bien, ¿estás intentando ocultar los cristales en mí? No puedo creer que no vi tu noble intención...",
  str_mail_vote_detail_53 = "¿Has estado votando por mí? ¿Has caído rendido ante mi encanto? ¿Por qué no vienes y tomas una copa conmigo después? Por supuesto, tú invitas.",
  str_mail_vote_detail_54 = "La gran fe vale la pena sacrificar todo; paz interior, cordura, incluso nuestra vida y alma... Gracias por apoyarme. Sería aún mejor si te unieras a nosotros.",
  str_mail_vote_detail_55 = "¿Así que tengo que estar dentro porque votaste por mí? ¡De ninguna manera, quiero ganar solo si no votaste por mí! ¿Entendido? Tu voto me hizo un poco feliz, pero solo un poco, así que no leas demasiado en ello!",
  str_mail_vote_detail_56 = "Por favor, no me pongas con nadie en la competencia. Me gusta mi espacio y tranquilidad... Espera, no te dije que te fueras. Además, gracias por tu apoyo...",
  str_mail_vote_detail_57 = "¡Vaya, nunca pensé que me apoyarías! ¿Supongo que has mejorado tu gusto en música? Entonces, déjame tocar una melodía para ti como mi más sincero agradecimiento.",
  str_mail_vote_detail_58 = "Aprecio tu apoyo que me dio el título. Gracias. He rechazado el honor antes porque recibí la felicidad hace mucho tiempo. Pero por ti y la búsqueda en el pasado con esa cierta persona, seguiré trabajando duro.",
  str_mail_vote_detail_59 = "La incineración convertirá toda belleza en cenizas, ¿entonces qué esperas? Tu idea es desconcertante... pero cumpliré tus expectativas como agradecimiento por haberme elegido.",
  str_mail_vote_detail_60 = "¿Quieres que tenga la oportunidad de un nuevo atuendo? A cambio, puedo contarte una historia de había una vez... Correcto, no tiene nada que ver con las estrellas sino con la ropa nueva del Emperador.",
  str_mail_vote_detail_61 = "¿Tienes algún problema con mi uniforme endeble? No importa. No importa lo que use, no disminuirá mi encanto y grandeza, pero aún mereces elogios por votar por la persona correcta.",
  str_mail_vote_detail_62 = "Gracias por el lindo gesto. Dado que todo existe en la voluntad de la naturaleza, ¿te gustaría dar un paseo por el bosque conmigo para disfrutar de la belleza de la naturaleza?",
  str_mail_vote_detail_63 = "Pareces muy interesado en cambiar mi apariencia. Desde tu voto, un símbolo llamado felicidad se ha añadido a mi memoria. Se sintió... maravilloso.",
  str_mail_vote_detail_64 = "¿El hecho de que votaste por mí tantas veces significa que te gusto mucho? Si Mia se entera, ¡podría llorar de felicidad!",
  str_mail_vote_detail_65 = "¿Es esta la idea de Dayna? ¿No? Pensé... ¿Así que así es como piensas de mí? Haré todo lo posible para no defraudarte...",
  str_mail_vote_detail_66 = "Estoy impactado. Debe haber cientos de Aurorians en el Colossus, sin embargo, votaste por mí. Te devolveré tu apoyo tres veces.",
  str_mail_vote_detail_67 = "Me alivia ver que estás bien ya que te tomaste el tiempo para preocuparte por lo que lleva un veterano. Acepto la oferta y cuídate.",
  str_mail_vote_detail_68 = "¿Voy a ser bonita? Gracias. No esperaba esto y estoy muy feliz.",
  str_mail_vote_detail_69 = "Normalmente, los jueces tienen su propio código de vestimenta. Sin embargo, ya que tú crees que hay una necesidad, lo aceptaré con gusto. Aprecio mucho esto, y hasta que nos volvamos a encontrar.",
  str_mail_vote_detail_70 = "Oye amigo, incluso los mercenarios saben que votaste por mí. Me conmueve que no me hayas olvidado. Gane o pierda, estoy dispuesto a lucir mejor para ti.",
  str_mail_vote_detail_71 = "Gracias, amigo. He visto innumerables ofrendas en Umbraton y no me siento así. ¿Quieres que gane esta vez...? Bueno, ¿qué tal si conseguimos que el gremio contribuya?",
  str_mail_vote_detail_72 = "He grabado tus pensamientos y consideraciones en el hielo del Palacio de Invierno. Me alegra ver que sigues siendo tan puro a pesar de todo lo que has pasado. Gracias.",
  str_mail_vote_detail_73 = "Veo que votaste por mí. Honestamente no esperaba saltar al escenario como organizador... Gracias, pero me preocupa más si disfrutaste de la festividad.",
  str_mail_vote_detail_74 = "¡Vaya, qué gran sorpresa! Siempre he querido ser parte de un evento como este, todo vestido y disfrutando del foco de atención. ¡Promete que estarás en el escenario conmigo!",
  str_mail_vote_detail_75 = "¿Estás envuelto en algún tipo de conspiración, Capitán, o estabas destinado a apoyar a un Ascendido como yo? ¡No tienes que decírmelo! Es esencial obtener apoyo en la lucha contra lo desconocido. ¡Gracias!",
  str_mail_vote_detail_76 = "¿Quieres verme en algo que no sea este uniforme? Puedo cumplir, si esa es tu solicitud. Para agradecerte, te invitaré a una ronda la próxima vez. No te preocupes, pediré algo normal.",
  str_mail_vote_detail_77 = "¡Noche Blanca en lo alto! ¿Es esto para mí? Sí, veo que tendré que esforzarme para cumplir con tus expectativas. Gracias, el último Caelestite. No olvides nutrirte y beber más agua.",
  str_mail_vote_detail_78 = "Oye, pequeña Caelestite, ¿es este voto para mí? Mmm... Ruby no parece estar aquí, entonces debo estar en lo correcto. ¡Gracias! Pero con tus halagos, ahora tengo que ganar, ¿no es así?!",
  str_mail_vote_detail_79 = "¡Si no es el Navegante! Hace mucho tiempo que no tengo un atuendo bonito. No importa el resultado, ¡aprecio mucho el pensamiento!",
  str_mail_vote_detail_80 = "¿Cuándo se volvió tan audaz el Navegante tímido? ¿Así que quieres verme con un cierto atuendo, verdad? No te preocupes, lo ganaré para ti.",
  str_mail_vote_detail_81 = "¡Tengo suficientes atuendos, niño! Y sigo arruinando los uniformes... Pero gracias de todos modos, niño. Para recompensarte, te haré una nueva agenda de entrenamiento solo para ti.",
  str_mail_vote_detail_82 = "El Gran Mariscal es el modelo a seguir de Illumina, ¿y quieres que me convierta en algo más? ¿Te lo estoy poniendo difícil? No importa, no puedo cuestionar la buena voluntad de un camarada, ¡así que gracias! Seré victorioso en el concurso.",
  str_mail_vote_detail_83 = "¿Quieres que Axelia se vea más bonita? Pero ya brillo. ¿Qué impresión dejaré con un disfraz diferente, sin embargo? Hmm, no estoy segura, pero sé que debo agradecerte.",
  str_mail_vote_detail_84 = "¡Oh, gracias por el apoyo! ¡Un nuevo atuendo reduciría cuántas veces regreso al Coloso con un uniforme manchado de sangre! Lo siento, espero no haberte asqueado cuando eso sucedió.",
  str_mail_vote_detail_85 = "Gracias por ayudarme. Votaré por ti si vuelve a suceder un concurso como este. Entonces, ¿qué opinas de una competencia por el cinturón más fuerte y ajustado?",
  str_mail_vote_detail_86 = "Veo que tienes el tiempo libre para presenciarme con un atuendo completamente nuevo... Lo aprecio. ¡Y dada la oportunidad, se me verá en todo mi esplendor!",
  str_mail_vote_detail_87 = "¿Te gustaría aprovechar esta oportunidad para hacerme un nuevo atuendo? Estoy agradecido y lo apreciaré. Sin embargo... ¿es posible hacer un disfraz de gatito para mi hermano?",
  str_mail_vote_detail_88 = "¿Deseas ordenar un nuevo atuendo para mí? Es muy considerado de tu parte. Aunque poseo un maravilloso guardarropa, palidece en presencia de tu dulce sinceridad.",
  str_mail_vote_detail_89 = "¿De verdad quieres arreglarme con algunos hilos bonitos? Muy agradecido. Y sabes que no sería justo si no hago algo bonito por ti a cambio, ¿verdad?",
  str_mail_vote_detail_90 = "¿Para mí? ¿Estás seguro? ¡Muchas gracias! No sé qué decir aparte de eso. Haré lo mejor que pueda, así que por favor sigue ayudándome.",
  str_mail_vote_detail_91 = "La ropa son simplemente coberturas, pero logras darles significados especiales. Gracias, joven Caelestite. Aprecio la sinceridad al darle un regalo a un mensajero.",
  str_mail_vote_detail_92 = "Bostezo... Oh, me siento mal al despertar y verte corriendo en mi nombre. Tengo que devolver el favor. Debería hacer... una nota de ello... en mi diario... bostezo...",
  str_mail_vote_detail_93 = "¡Estoy agradecido por tu voto! Solo me uní para garantizar la justicia de la competencia y los resultados no significan mucho para mí, pero aún me siento honrado de tener tu reconocimiento.",
  str_mail_vote_detail_94 = "¿Quieres verme en un traje de campesino, verdad? ¡Te haré saber que mi familia está en el negocio del lujo! Tomaré el voto si insistes, pero ¿cómo puede ser suficiente uno solo?!",
  str_mail_vote_detail_95 = "Gracias por tu voto, aunque no estoy seguro de ganar un evento tan vibrante, para ser honesto. Sin embargo, si estás interesado, podemos encontrarnos fuera del escenario. Tengo muchos datos divertidos para compartir.",
  str_mail_vote_detail_96 = "Gracias. No esperaba que te importara si tengo suficientes disfraces para la infiltración. Incluso si no gano un nuevo atuendo adecuado para las misiones, me aseguraré de poder acomodar la próxima asignación de ti.",
  str_mail_vote_detail_97 = "Me siento culpable por todo el apoyo que me estás ofreciendo. Te prometí un aprendizaje y comidas gourmet hechas por gadgets, solo para que me des atuendos sin que yo cumpla nada. Estoy avergonzado. ¡Escribiré mi nombre al revés si no cumplo la próxima vez!",
  str_mail_vote_detail_98 = "¡Wow, gracias por votar para hacerme un traje nuevo! ¡Un voto, un voto, tengo un voto! Puede que no consiga un traje nuevo, ¡pero no me importa! ¡Un verdadero amigo es mejor que cualquier ropa!",
  str_mail_vote_detail_99 = "¿Quieres conseguirme un nuevo disfraz? Esto es vergonzoso... No creo que sea digno de ello ya que corro por las montañas todo el día. Pero puedo darte unas bonitas pulseras, eso sí.",
  str_mail_vote_detail_100 = "Gracias, Navegante. Aún me tienes en mente incluso en un concurso como este, ayudándome a ganar. En realidad, no me importa mucho la apariencia, pero lo recordaré.",
  str_mail_vote_detail_101 = "¿Bono del Último Caelestite? ¿Una recompensa para Zeta el Guerrero? ¡Vaya, qué maravilloso, Último Caelestite! Solo observa, ¡Zeta es invencible!",
  str_mail_vote_detail_102 = "Gracias... Desde todas las perspectivas, la apariencia sirve para cubrir partes de alto rendimiento poco atractivas. Pero en lugar de gastar dinero en ello, ¡sería mejor si fuera gratis!",
  str_mail_vote_detail_103 = "En este largo viaje, a menudo recuerdo a esos compañeros que lucharon a mi lado; su coraje y fuerza me dieron innumerables alentamientos. He visto a innumerables enemigos caer bajo mi espada y he sentido el dolor y la fatiga traídos por la batalla. Pero cada vez que giro mi espada, es un compromiso firme con mis creencias. Creo que la espada no es solo una arma, sino también un símbolo del espíritu, una voluntad inflexible."
}
return config
